window.AP_STATISTICS_DECKS = [{"id":"apstats-unit-1","name":"AP Statistics · Unit 1","shortName":"Unit 1: Exploring One-Variable Data and Collecting Data","builtIn":true,"sourceTitle":"AP Statistics Course and Exam Description, Effective Fall 2026","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-statistics-course-and-exam-description-effective-fall-2026.pdf","cards":[{"id":"apstats-u1-c1","front":"statistical study","back":"A study that collects data from a sample to answer an investigative question about a larger population."},{"id":"apstats-u1-c2","front":"investigative question","back":"A question with a defined purpose that can be answered by collecting and analyzing data."},{"id":"apstats-u1-c3","front":"population","back":"The entire group of individuals or items about which a study seeks information."},{"id":"apstats-u1-c4","front":"sample","back":"The subset of a population from which data are actually collected."},{"id":"apstats-u1-c5","front":"observational unit","back":"An individual or item from which a datum is collected."},{"id":"apstats-u1-c6","front":"variable","back":"A characteristic that can vary from one observational unit to another."},{"id":"apstats-u1-c7","front":"categorical variable","back":"A variable whose values place observational units into groups or categories."},{"id":"apstats-u1-c8","front":"quantitative variable","back":"A variable whose numerical values represent measured or counted quantities."},{"id":"apstats-u1-c9","front":"discrete quantitative variable","back":"A quantitative variable with a finite or countably infinite set of possible values."},{"id":"apstats-u1-c10","front":"continuous quantitative variable","back":"A quantitative variable that can take any value within an interval."},{"id":"apstats-u1-c11","front":"parameter","back":"A numerical value that describes a population."},{"id":"apstats-u1-c12","front":"statistic","back":"A numerical value calculated from sample data."},{"id":"apstats-u1-c13","front":"frequency table","back":"A table showing the count of observational units in each category."},{"id":"apstats-u1-c14","front":"relative frequency table","back":"A table showing the proportion or percentage of observational units in each category."},{"id":"apstats-u1-c15","front":"bar chart","back":"A graph using separated bars to display frequencies or relative frequencies of categories."},{"id":"apstats-u1-c16","front":"pie chart","back":"A circle divided into sectors whose areas represent category proportions."},{"id":"apstats-u1-c17","front":"dotplot","back":"A quantitative-data display that places a dot for each observation above its value on a number line."},{"id":"apstats-u1-c18","front":"stem-and-leaf plot","back":"A quantitative-data display that separates each value into a stem and a leaf while preserving individual observations."},{"id":"apstats-u1-c19","front":"histogram","back":"A graph using adjacent bars to display frequencies or relative frequencies across quantitative intervals."},{"id":"apstats-u1-c20","front":"distribution","back":"The pattern of values a variable takes, described by shape, center, variability, and unusual features."},{"id":"apstats-u1-c21","front":"unimodal distribution","back":"A distribution with one prominent peak."},{"id":"apstats-u1-c22","front":"bimodal distribution","back":"A distribution with two prominent peaks."},{"id":"apstats-u1-c23","front":"symmetric distribution","back":"A distribution whose two sides are approximately mirror images."},{"id":"apstats-u1-c24","front":"skewed right","back":"A distribution with a longer tail toward larger values."},{"id":"apstats-u1-c25","front":"skewed left","back":"A distribution with a longer tail toward smaller values."},{"id":"apstats-u1-c26","front":"mean","back":"The arithmetic average of a quantitative data set; it is sensitive to extreme values."},{"id":"apstats-u1-c27","front":"median","back":"The middle ordered value, or the average of the two middle values; it is resistant to extreme values."},{"id":"apstats-u1-c28","front":"range","back":"The maximum value minus the minimum value."},{"id":"apstats-u1-c29","front":"first quartile (Q1)","back":"The median of the lower half of an ordered data set."},{"id":"apstats-u1-c30","front":"third quartile (Q3)","back":"The median of the upper half of an ordered data set."},{"id":"apstats-u1-c31","front":"interquartile range (IQR)","back":"The spread of the middle 50% of data, calculated as Q3 minus Q1."},{"id":"apstats-u1-c32","front":"standard deviation","back":"A measure of typical distance between observations and their mean."},{"id":"apstats-u1-c33","front":"variance","back":"The square of the standard deviation; the average squared deviation using the appropriate population or sample divisor."},{"id":"apstats-u1-c34","front":"five-number summary","back":"The minimum, Q1, median, Q3, and maximum of a quantitative data set."},{"id":"apstats-u1-c35","front":"boxplot","back":"A graph based on the five-number summary that displays center, spread, and potential outliers."},{"id":"apstats-u1-c36","front":"potential outlier","back":"A value below Q1 - 1.5(IQR) or above Q3 + 1.5(IQR)."},{"id":"apstats-u1-c37","front":"z-score","back":"The number of standard deviations a value lies above or below the mean."},{"id":"apstats-u1-c38","front":"percentile","back":"The percentage of observations at or below a specified value."},{"id":"apstats-u1-c39","front":"resistant statistic","back":"A statistic that is not strongly affected by extreme observations, such as the median or IQR."},{"id":"apstats-u1-c40","front":"observational study","back":"A study that observes variables without assigning treatments to experimental units."},{"id":"apstats-u1-c41","front":"experiment","back":"A study in which researchers assign treatments to experimental units to investigate their effects."},{"id":"apstats-u1-c42","front":"explanatory variable","back":"A variable that may explain or predict changes in a response variable."},{"id":"apstats-u1-c43","front":"response variable","back":"The outcome variable measured in a study."},{"id":"apstats-u1-c44","front":"confounding variable","back":"A variable related to both the explanatory and response variables that provides an alternative explanation for an observed association."},{"id":"apstats-u1-c45","front":"sampling frame","back":"The list or practical representation of the population from which a sample is selected."},{"id":"apstats-u1-c46","front":"census","back":"An attempt to collect data from every member of a population."},{"id":"apstats-u1-c47","front":"random sample","back":"A sample selected using chance so that selection probabilities are known."},{"id":"apstats-u1-c48","front":"simple random sample (SRS)","back":"A sample selected so every possible sample of a given size has an equal chance of selection."},{"id":"apstats-u1-c49","front":"stratified random sample","back":"A sample formed by dividing a population into homogeneous strata and taking an SRS from every stratum."},{"id":"apstats-u1-c50","front":"cluster random sample","back":"A sample formed by dividing a population into clusters that each resemble the population, randomly selecting clusters, and sampling everyone in the chosen clusters."},{"id":"apstats-u1-c51","front":"systematic random sample","back":"A sample created by choosing a random starting point and then selecting every kth member of an ordered population."},{"id":"apstats-u1-c52","front":"multistage random sample","back":"A sample selected through multiple random stages, often combining cluster and simple random sampling."},{"id":"apstats-u1-c53","front":"sampling with replacement","back":"A method in which a selected observational unit is returned and may be selected again."},{"id":"apstats-u1-c54","front":"sampling without replacement","back":"A method in which each selected observational unit can appear only once."},{"id":"apstats-u1-c55","front":"convenience sample","back":"A sample chosen from individuals easiest to reach; it commonly produces selection bias."},{"id":"apstats-u1-c56","front":"voluntary response sample","back":"A sample consisting of people who choose themselves by responding to an open invitation."},{"id":"apstats-u1-c57","front":"bias","back":"A systematic error that makes a sample statistic consistently too high or too low for the parameter it estimates."},{"id":"apstats-u1-c58","front":"selection bias","back":"Bias caused when some groups are systematically overrepresented or underrepresented by the sampling method."},{"id":"apstats-u1-c59","front":"undercoverage","back":"Selection bias that occurs when some groups are left out or inadequately represented in the sampling frame."},{"id":"apstats-u1-c60","front":"nonresponse bias","back":"Bias that can occur when selected individuals who do not respond differ meaningfully from those who do."},{"id":"apstats-u1-c61","front":"response bias","back":"Bias caused by inaccurate answers resulting from wording, interviewer influence, social desirability, faulty memory, or other response effects."},{"id":"apstats-u1-c62","front":"random assignment","back":"Use of chance to assign treatments, helping create comparable groups and permitting cause-and-effect conclusions."},{"id":"apstats-u1-c63","front":"treatment","back":"A specific experimental condition imposed on an experimental unit."},{"id":"apstats-u1-c64","front":"experimental unit","back":"The observational unit to which a treatment is assigned."},{"id":"apstats-u1-c65","front":"factor","back":"An explanatory variable whose levels are controlled by the experimenter."},{"id":"apstats-u1-c66","front":"level","back":"A specific value or category of an experimental factor."},{"id":"apstats-u1-c67","front":"control group","back":"A comparison group that receives a standard treatment, placebo, or no treatment."},{"id":"apstats-u1-c68","front":"placebo","back":"An inert treatment designed to resemble an active treatment."},{"id":"apstats-u1-c69","front":"placebo effect","back":"A response caused by the expectation of receiving a treatment rather than by the treatment itself."},{"id":"apstats-u1-c70","front":"single-blind experiment","back":"An experiment in which participants do not know which treatment they receive, or evaluators do not know which treatment was assigned."},{"id":"apstats-u1-c71","front":"double-blind experiment","back":"An experiment in which neither participants nor response evaluators know treatment assignments."},{"id":"apstats-u1-c72","front":"replication","back":"Use of enough experimental units in each treatment group to estimate treatment effects and natural variability."},{"id":"apstats-u1-c73","front":"completely randomized design","back":"An experimental design that assigns all treatments to all experimental units entirely by chance."},{"id":"apstats-u1-c74","front":"randomized block design","back":"An experimental design that groups similar units into blocks and randomly assigns treatments within each block."},{"id":"apstats-u1-c75","front":"matched pairs design","back":"A block design comparing two treatments by matching similar units or applying both treatments to each unit in randomized order."},{"id":"apstats-u1-c76","front":"block","back":"A group of experimental units similar in a characteristic expected to affect the response."},{"id":"apstats-u1-c77","front":"statistical significance","back":"A result unlikely to occur by chance alone under a specified null model."},{"id":"apstats-u1-c78","front":"scope of inference","back":"The population and type of conclusion supported by a study's sampling and assignment methods."},{"id":"apstats-u1-eq1","front":"Sample mean","back":"Use to calculate the arithmetic average of n observations.","backImage":"./ap-statistics-images/unit-1-formula-1.svg"},{"id":"apstats-u1-eq2","front":"Sample standard deviation","back":"Use to measure typical distance from the sample mean.","backImage":"./ap-statistics-images/unit-1-formula-2.svg"},{"id":"apstats-u1-eq3","front":"Interquartile range","back":"Use to measure the spread of the middle half of a distribution.","backImage":"./ap-statistics-images/unit-1-formula-3.svg"},{"id":"apstats-u1-eq4","front":"Outlier fences","back":"Use to flag potential low and high outliers.","backImage":"./ap-statistics-images/unit-1-formula-4.svg"},{"id":"apstats-u1-eq5","front":"z-score","back":"Use to express a value's distance from the mean in standard deviations.","backImage":"./ap-statistics-images/unit-1-formula-5.svg"}],"questions":[],"feynmanPrompts":[{"id":"apstats-u1-f1","prompt":"Choosing a sampling method"},{"id":"apstats-u1-f2","prompt":"Sources of sampling bias"},{"id":"apstats-u1-f3","prompt":"Observational studies vs. experiments"},{"id":"apstats-u1-f4","prompt":"Random assignment and causal inference"},{"id":"apstats-u1-f5","prompt":"Designing a controlled experiment"},{"id":"apstats-u1-f6","prompt":"Describing a quantitative distribution"},{"id":"apstats-u1-f7","prompt":"Center, spread, and resistant statistics"}]},{"id":"apstats-unit-2","name":"AP Statistics · Unit 2","shortName":"Unit 2: Probability, Random Variables, and Probability Distributions","builtIn":true,"sourceTitle":"AP Statistics Course and Exam Description, Effective Fall 2026","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-statistics-course-and-exam-description-effective-fall-2026.pdf","cards":[{"id":"apstats-u2-c1","front":"random process","back":"A repeatable process whose individual outcomes are uncertain but whose long-run pattern is predictable."},{"id":"apstats-u2-c2","front":"sample space","back":"The set of all possible outcomes of a random process."},{"id":"apstats-u2-c3","front":"event","back":"A subset of outcomes in a sample space."},{"id":"apstats-u2-c4","front":"probability","back":"A number from 0 to 1 describing the long-run relative frequency of an event."},{"id":"apstats-u2-c5","front":"complement rule","back":"The probability that event A does not occur equals 1 minus the probability that A occurs."},{"id":"apstats-u2-c6","front":"addition rule","back":"A rule for finding the probability that event A or event B occurs while avoiding double-counting their overlap."},{"id":"apstats-u2-c7","front":"disjoint events","back":"Events that cannot occur at the same time."},{"id":"apstats-u2-c8","front":"conditional probability","back":"The probability of an event given that another event has occurred."},{"id":"apstats-u2-c9","front":"independent events","back":"Events for which knowing one occurred does not change the probability of the other."},{"id":"apstats-u2-c10","front":"multiplication rule","back":"A rule expressing a joint probability as a conditional probability multiplied by a marginal probability."},{"id":"apstats-u2-c11","front":"two-way table","back":"A table displaying counts or relative frequencies for two categorical variables."},{"id":"apstats-u2-c12","front":"marginal distribution","back":"The distribution of one categorical variable using row or column totals from a two-way table."},{"id":"apstats-u2-c13","front":"conditional distribution","back":"The distribution of one categorical variable within a fixed category of another variable."},{"id":"apstats-u2-c14","front":"simulation","back":"Use of a chance process to imitate repeated trials and estimate a probability."},{"id":"apstats-u2-c15","front":"random variable","back":"A numerical variable whose value is determined by the outcome of a random process."},{"id":"apstats-u2-c16","front":"probability distribution","back":"A listing or model that assigns probabilities to possible values of a random variable."},{"id":"apstats-u2-c17","front":"expected value","back":"The long-run average value of a random variable over many repetitions."},{"id":"apstats-u2-c18","front":"linear transformation","back":"A transformation of the form a + bX that shifts and rescales a random variable."},{"id":"apstats-u2-c19","front":"binomial setting","back":"A fixed number of independent trials with two outcomes and constant success probability."},{"id":"apstats-u2-c20","front":"binomial random variable","back":"The number of successes in a fixed number of independent Bernoulli trials."},{"id":"apstats-u2-c21","front":"binomial coefficient","back":"The number of different ways to choose x successes from n trials."},{"id":"apstats-u2-c22","front":"geometric setting","back":"Independent trials with two outcomes and constant success probability, repeated until the first success."},{"id":"apstats-u2-c23","front":"geometric random variable","back":"The number of trials required to obtain the first success."},{"id":"apstats-u2-c24","front":"normal distribution","back":"A symmetric bell-shaped continuous distribution determined by its mean and standard deviation."},{"id":"apstats-u2-c25","front":"standard normal distribution","back":"The normal distribution with mean 0 and standard deviation 1."},{"id":"apstats-u2-c26","front":"normal probability plot","back":"A graph used to assess normality; approximately linear points support a normal model."},{"id":"apstats-u2-c27","front":"law of large numbers","back":"As the number of independent repetitions increases, a sample mean or proportion tends to approach its expected value."},{"id":"apstats-u2-eq1","front":"Addition rule","back":"Use to find the probability of A or B without double-counting their overlap.","backImage":"./ap-statistics-images/unit-2-formula-1.svg"},{"id":"apstats-u2-eq2","front":"Conditional probability","back":"Use to find the probability of A given that B occurred.","backImage":"./ap-statistics-images/unit-2-formula-2.svg"},{"id":"apstats-u2-eq3","front":"Expected value of a random variable","back":"Use to find the long-run mean of a discrete random variable.","backImage":"./ap-statistics-images/unit-2-formula-3.svg"},{"id":"apstats-u2-eq4","front":"Standard deviation of a random variable","back":"Use to measure spread around a discrete random variable's expected value.","backImage":"./ap-statistics-images/unit-2-formula-4.svg"},{"id":"apstats-u2-eq5","front":"Binomial probability","back":"Use for exactly x successes in n independent trials with constant success probability p.","backImage":"./ap-statistics-images/unit-2-formula-5.svg"},{"id":"apstats-u2-eq6","front":"Binomial mean and standard deviation","back":"Use for the center and spread of a binomial random variable.","backImage":"./ap-statistics-images/unit-2-formula-6.svg"},{"id":"apstats-u2-eq7","front":"Geometric probability","back":"Use for the probability that the first success occurs on trial x.","backImage":"./ap-statistics-images/unit-2-formula-7.svg"},{"id":"apstats-u2-eq8","front":"Geometric mean","back":"Use for the expected number of trials until the first success.","backImage":"./ap-statistics-images/unit-2-formula-8.svg"}],"questions":[],"feynmanPrompts":[{"id":"apstats-u2-f1","prompt":"Conditional probability and independence"},{"id":"apstats-u2-f2","prompt":"Building a probability model"},{"id":"apstats-u2-f3","prompt":"Binomial vs. geometric distributions"},{"id":"apstats-u2-f4","prompt":"Combining random variables"}]},{"id":"apstats-unit-3","name":"AP Statistics · Unit 3","shortName":"Unit 3: Inference for Categorical Data: Proportions","builtIn":true,"sourceTitle":"AP Statistics Course and Exam Description, Effective Fall 2026","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-statistics-course-and-exam-description-effective-fall-2026.pdf","cards":[{"id":"apstats-u3-c1","front":"estimator","back":"A statistic used to estimate an unknown population parameter."},{"id":"apstats-u3-c2","front":"point estimate","back":"A single statistic used as the best estimate of a population parameter."},{"id":"apstats-u3-c3","front":"unbiased estimator","back":"An estimator whose sampling distribution has a mean equal to the parameter being estimated."},{"id":"apstats-u3-c4","front":"sampling distribution","back":"The distribution of a statistic over all possible samples of a fixed size from a population."},{"id":"apstats-u3-c5","front":"sampling variability","back":"Natural sample-to-sample variation in a statistic."},{"id":"apstats-u3-c6","front":"standard error","back":"An estimate of the standard deviation of a statistic's sampling distribution."},{"id":"apstats-u3-c7","front":"central limit theorem","back":"A result explaining when a standardized sampling distribution is approximately normal."},{"id":"apstats-u3-c8","front":"10% condition","back":"When sampling without replacement, the sample should be no more than 10% of the population to treat observations as approximately independent."},{"id":"apstats-u3-c9","front":"large-counts condition","back":"A success-failure condition requiring sufficiently large expected counts for a normal approximation."},{"id":"apstats-u3-c10","front":"confidence interval","back":"An interval of plausible values for a population parameter calculated from sample data."},{"id":"apstats-u3-c11","front":"confidence level","back":"The long-run percentage of intervals from repeated random samples that capture the true parameter."},{"id":"apstats-u3-c12","front":"critical value","back":"A multiplier from a reference distribution that determines the confidence interval's margin of error."},{"id":"apstats-u3-c13","front":"margin of error","back":"The critical value multiplied by the standard error."},{"id":"apstats-u3-c14","front":"one-proportion z-interval","back":"A confidence interval for one population proportion based on a sample proportion and an unpooled standard error."},{"id":"apstats-u3-c15","front":"null hypothesis","back":"A statement about a population parameter treated as true while calculating a test probability."},{"id":"apstats-u3-c16","front":"alternative hypothesis","back":"The claim supported when the data provide sufficiently strong evidence against the null hypothesis."},{"id":"apstats-u3-c17","front":"significance level","back":"The chosen probability threshold alpha for deciding whether evidence against the null hypothesis is strong enough."},{"id":"apstats-u3-c18","front":"test statistic","back":"A standardized measure of how far a sample statistic lies from the null-hypothesized parameter value."},{"id":"apstats-u3-c19","front":"p-value","back":"Assuming the null hypothesis is true, the probability of a test statistic at least as extreme as the observed result in the direction of the alternative."},{"id":"apstats-u3-c20","front":"one-proportion z-test","back":"A significance test for a claim about one population proportion."},{"id":"apstats-u3-c21","front":"Type I error","back":"Rejecting a true null hypothesis; its probability is alpha."},{"id":"apstats-u3-c22","front":"Type II error","back":"Failing to reject a false null hypothesis; its probability is beta."},{"id":"apstats-u3-c23","front":"power","back":"The probability that a test correctly rejects a false null hypothesis."},{"id":"apstats-u3-c24","front":"statistically significant result","back":"A test result with a p-value less than or equal to the chosen significance level."},{"id":"apstats-u3-c25","front":"practically significant result","back":"A result large enough to matter in its real-world context, regardless of statistical significance."},{"id":"apstats-u3-c26","front":"sampling distribution of a difference in proportions","back":"The distribution of p-hat1 minus p-hat2 across repeated independent samples."},{"id":"apstats-u3-c27","front":"two-proportion z-interval","back":"A confidence interval for the difference between two population proportions using an unpooled standard error."},{"id":"apstats-u3-c28","front":"pooled sample proportion","back":"The combined successes divided by the combined sample size, used in a two-proportion z-test under equality of proportions."},{"id":"apstats-u3-c29","front":"two-proportion z-test","back":"A significance test comparing two population proportions under a null hypothesis of equality."},{"id":"apstats-u3-c30","front":"chi-square statistic","back":"A sum measuring discrepancy between observed and expected categorical counts."},{"id":"apstats-u3-c31","front":"chi-square goodness-of-fit test","back":"A test of whether one categorical variable follows a specified distribution."},{"id":"apstats-u3-c32","front":"chi-square test for homogeneity","back":"A test comparing the distribution of one categorical variable across several populations or treatments."},{"id":"apstats-u3-c33","front":"chi-square test for independence","back":"A test of association between two categorical variables within one population."},{"id":"apstats-u3-c34","front":"expected count","back":"The count predicted for a category or table cell when the null hypothesis is true."},{"id":"apstats-u3-c35","front":"degrees of freedom","back":"A quantity determining the chi-square or t reference distribution after accounting for constraints."},{"id":"apstats-u3-c36","front":"chi-square contribution","back":"A cell's contribution, (observed - expected)^2 / expected, to the total chi-square statistic."},{"id":"apstats-u3-eq1","front":"Sampling distribution of p-hat","back":"Use for the mean and standard deviation of a sample proportion.","backImage":"./ap-statistics-images/unit-3-formula-1.svg"},{"id":"apstats-u3-eq2","front":"One-proportion z-interval","back":"Use to estimate one population proportion.","backImage":"./ap-statistics-images/unit-3-formula-2.svg"},{"id":"apstats-u3-eq3","front":"One-proportion z-test","back":"Use to test H₀: p = p₀. The null value p₀ belongs in the standard error.","backImage":"./ap-statistics-images/unit-3-formula-3.svg"},{"id":"apstats-u3-eq4","front":"Two-proportion z-interval","back":"Use to estimate p₁ − p₂ with independent samples.","backImage":"./ap-statistics-images/unit-3-formula-4.svg"},{"id":"apstats-u3-eq5","front":"Pooled proportion","back":"Use in a two-proportion z-test under H₀: p₁ = p₂.","backImage":"./ap-statistics-images/unit-3-formula-5.svg"},{"id":"apstats-u3-eq6","front":"Two-proportion z-test","back":"Use to test H₀: p₁ = p₂ using the pooled proportion.","backImage":"./ap-statistics-images/unit-3-formula-6.svg"},{"id":"apstats-u3-eq7","front":"Chi-square statistic","back":"Use to compare observed categorical counts with counts expected under H₀.","backImage":"./ap-statistics-images/unit-3-formula-7.svg"},{"id":"apstats-u3-eq8","front":"Expected count in a two-way table","back":"Use under a chi-square null model for a table cell.","backImage":"./ap-statistics-images/unit-3-formula-8.svg"}],"questions":[],"feynmanPrompts":[{"id":"apstats-u3-f1","prompt":"Sampling distributions for proportions"},{"id":"apstats-u3-f2","prompt":"Confidence intervals for proportions"},{"id":"apstats-u3-f3","prompt":"Logic of significance testing"},{"id":"apstats-u3-f4","prompt":"Type I error, Type II error, and power"},{"id":"apstats-u3-f5","prompt":"One proportion vs. two proportions"},{"id":"apstats-u3-f6","prompt":"Choosing among chi-square procedures"}]},{"id":"apstats-unit-4","name":"AP Statistics · Unit 4","shortName":"Unit 4: Inference for Quantitative Data: Means","builtIn":true,"sourceTitle":"AP Statistics Course and Exam Description, Effective Fall 2026","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-statistics-course-and-exam-description-effective-fall-2026.pdf","cards":[{"id":"apstats-u4-c1","front":"sampling distribution of a sample mean","back":"The distribution of x-bar over all possible random samples of a fixed size."},{"id":"apstats-u4-c2","front":"standard error of the sample mean","back":"The estimated standard deviation of the sampling distribution of x-bar, calculated with s divided by square root of n."},{"id":"apstats-u4-c3","front":"t-distribution","back":"A symmetric distribution with heavier tails than the standard normal distribution; its shape depends on degrees of freedom."},{"id":"apstats-u4-c4","front":"degrees of freedom for one-sample t","back":"For a one-sample t procedure, df equals n minus 1."},{"id":"apstats-u4-c5","front":"one-sample t-interval","back":"A confidence interval for a population mean when the population standard deviation is unknown."},{"id":"apstats-u4-c6","front":"paired data","back":"Observations linked in meaningful pairs, such as before-and-after measurements on the same subjects."},{"id":"apstats-u4-c7","front":"mean difference","back":"The average of within-pair differences in a matched-pairs analysis."},{"id":"apstats-u4-c8","front":"matched-pairs t-interval","back":"A one-sample t-interval applied to paired differences."},{"id":"apstats-u4-c9","front":"one-sample t-test","back":"A significance test for a population mean when the population standard deviation is unknown."},{"id":"apstats-u4-c10","front":"matched-pairs t-test","back":"A one-sample t-test applied to paired differences."},{"id":"apstats-u4-c11","front":"robust procedure","back":"A method that continues to work reasonably well when assumptions are moderately violated."},{"id":"apstats-u4-c12","front":"two-sample t-interval","back":"A confidence interval for the difference between two independent population means."},{"id":"apstats-u4-c13","front":"two-sample t-test","back":"A significance test comparing two independent population means."},{"id":"apstats-u4-c14","front":"independent samples","back":"Samples whose observations and selection processes do not influence one another."},{"id":"apstats-u4-c15","front":"pooled t-procedure","back":"A two-sample method that assumes equal population variances; it is generally not the default AP Statistics procedure."},{"id":"apstats-u4-c16","front":"standard error for two means","back":"The square root of s1 squared over n1 plus s2 squared over n2."},{"id":"apstats-u4-c17","front":"sample-size effect","back":"Larger samples reduce standard error and usually produce narrower intervals and more powerful tests."},{"id":"apstats-u4-c18","front":"confidence-level effect","back":"Higher confidence requires a larger critical value and produces a wider confidence interval."},{"id":"apstats-u4-eq1","front":"Sampling distribution of x-bar","back":"Use for the mean and standard deviation of a sample mean.","backImage":"./ap-statistics-images/unit-4-formula-1.svg"},{"id":"apstats-u4-eq2","front":"One-sample t-interval","back":"Use to estimate a population mean when σ is unknown.","backImage":"./ap-statistics-images/unit-4-formula-2.svg"},{"id":"apstats-u4-eq3","front":"One-sample t-test","back":"Use to test H₀: μ = μ₀ when σ is unknown.","backImage":"./ap-statistics-images/unit-4-formula-3.svg"},{"id":"apstats-u4-eq4","front":"Matched-pairs t-test","back":"Use a one-sample t-test on paired differences.","backImage":"./ap-statistics-images/unit-4-formula-4.svg"},{"id":"apstats-u4-eq5","front":"Two-sample t-interval","back":"Use to estimate μ₁ − μ₂ from independent samples.","backImage":"./ap-statistics-images/unit-4-formula-5.svg"},{"id":"apstats-u4-eq6","front":"Two-sample t-test","back":"Use to test a difference between two independent population means.","backImage":"./ap-statistics-images/unit-4-formula-6.svg"}],"questions":[],"feynmanPrompts":[{"id":"apstats-u4-f1","prompt":"Sampling distributions for means"},{"id":"apstats-u4-f2","prompt":"The t-distribution"},{"id":"apstats-u4-f3","prompt":"Matched pairs vs. independent samples"},{"id":"apstats-u4-f4","prompt":"Confidence intervals and tests for means"}]},{"id":"apstats-unit-5","name":"AP Statistics · Unit 5","shortName":"Unit 5: Regression Analysis","builtIn":true,"sourceTitle":"AP Statistics Course and Exam Description, Effective Fall 2026","sourceUrl":"https://apcentral.collegeboard.org/media/pdf/ap-statistics-course-and-exam-description-effective-fall-2026.pdf","cards":[{"id":"apstats-u5-c1","front":"bivariate quantitative data","back":"Ordered pairs of observations measured on two quantitative variables."},{"id":"apstats-u5-c2","front":"scatterplot","back":"A graph of paired quantitative data used to examine form, direction, strength, and unusual features."},{"id":"apstats-u5-c3","front":"association","back":"A relationship in which values of one variable tend to occur with particular values of another."},{"id":"apstats-u5-c4","front":"positive association","back":"An association in which larger values of one variable tend to occur with larger values of the other."},{"id":"apstats-u5-c5","front":"negative association","back":"An association in which larger values of one variable tend to occur with smaller values of the other."},{"id":"apstats-u5-c6","front":"correlation coefficient","back":"The unit-free statistic r measuring direction and strength of a linear association, from -1 to 1."},{"id":"apstats-u5-c7","front":"linear regression model","back":"An equation using an explanatory variable to predict a quantitative response variable."},{"id":"apstats-u5-c8","front":"explanatory variable in regression","back":"The x-variable used to predict or explain changes in the response."},{"id":"apstats-u5-c9","front":"response variable in regression","back":"The y-variable being predicted by a regression model."},{"id":"apstats-u5-c10","front":"least-squares regression line","back":"The line minimizing the sum of squared residuals."},{"id":"apstats-u5-c11","front":"predicted value","back":"The response value y-hat produced by a regression equation for a given x-value."},{"id":"apstats-u5-c12","front":"residual","back":"Observed response minus predicted response."},{"id":"apstats-u5-c13","front":"residual plot","back":"A graph of residuals against explanatory values or predicted values used to assess model fit."},{"id":"apstats-u5-c14","front":"coefficient of determination","back":"The value r-squared, interpreted as the proportion of response variability explained by the linear model."},{"id":"apstats-u5-c15","front":"slope of a regression line","back":"The predicted change in the response variable for a one-unit increase in the explanatory variable."},{"id":"apstats-u5-c16","front":"y-intercept of a regression line","back":"The predicted response when x equals zero, meaningful only when zero is relevant and within the model's scope."},{"id":"apstats-u5-c17","front":"influential point","back":"A point whose removal substantially changes a regression model or another summary."},{"id":"apstats-u5-c18","front":"high-leverage point","back":"A point with an unusual explanatory-variable value that has potential to strongly affect the regression line."},{"id":"apstats-u5-c19","front":"extrapolation","back":"Use of a model to predict outside the range of observed explanatory values; such predictions may be unreliable."},{"id":"apstats-u5-c20","front":"correlation is not causation","back":"A strong association alone does not establish that changes in one variable cause changes in another."},{"id":"apstats-u5-c21","front":"standard error of the slope","back":"The estimated standard deviation of the sampling distribution of the least-squares slope."},{"id":"apstats-u5-c22","front":"t-test for a regression slope","back":"A test of whether the population regression slope differs from a hypothesized value, usually zero."},{"id":"apstats-u5-c23","front":"t-interval for a regression slope","back":"A confidence interval estimating the population slope of a linear regression model."},{"id":"apstats-u5-eq1","front":"Least-squares regression line","back":"Use to predict a response y from an explanatory value x.","backImage":"./ap-statistics-images/unit-5-formula-1.svg"},{"id":"apstats-u5-eq2","front":"Regression slope","back":"Use to calculate the least-squares slope from correlation and sample standard deviations.","backImage":"./ap-statistics-images/unit-5-formula-2.svg"},{"id":"apstats-u5-eq3","front":"Regression intercept","back":"Use to calculate the intercept after finding the slope.","backImage":"./ap-statistics-images/unit-5-formula-3.svg"},{"id":"apstats-u5-eq4","front":"Residual","back":"Use to measure prediction error for an observation.","backImage":"./ap-statistics-images/unit-5-formula-4.svg"},{"id":"apstats-u5-eq5","front":"Correlation coefficient","back":"Use to standardize and summarize linear association.","backImage":"./ap-statistics-images/unit-5-formula-5.svg"},{"id":"apstats-u5-eq6","front":"t-test for regression slope","back":"Use to test H₀: β = 0 for a linear population model.","backImage":"./ap-statistics-images/unit-5-formula-6.svg"}],"questions":[],"feynmanPrompts":[{"id":"apstats-u5-f1","prompt":"Interpreting correlation and regression"},{"id":"apstats-u5-f2","prompt":"Residuals and model fit"},{"id":"apstats-u5-f3","prompt":"Influential points and extrapolation"}]}];
